1	/**
2	 * Converts Vercel AI SDK stream events to OpenAI ChatCompletionChunk format
3	 */
4	
5	import type { ChatCompletionChunk } from "openai/resources/index";
6	import { chatChunk, chatChunkFromDelta, usageChatChunk } from "./util.js";
7	
8	export type VercelStreamPart =
9	  | { type: "text-delta"; textDelta: string }
10	  | { type: "reasoning"; textDelta: string }
11	  | { type: "reasoning-signature"; signature: string }
12	  | { type: "redacted-reasoning"; data: string }
13	  | { type: "source"; source: any }
14	  | { type: "file"; name: string; content: string }
15	  | {
16	      type: "tool-call";
17	      toolCallId: string;
18	      toolName: string;
19	      args: Record<string, unknown>;
20	    }
21	  | {
22	      type: "tool-call-streaming-start";
23	      toolCallId: string;
24	      toolName: string;
25	    }
26	  | {
27	      type: "tool-call-delta";
28	      toolCallId: string;
29	      toolName: string;
30	      argsTextDelta: string;
31	    }
32	  | { type: "tool-result"; toolCallId: string; result: unknown }
33	  | {
34	      type: "step-start";
35	      messageId: string;
36	      request: any;
37	      warnings: any[];
38	    }
39	  | {
40	      type: "step-finish";
41	      messageId: string;
42	      request: any;
43	      response: any;
44	      usage: {
45	        promptTokens: number;
46	        completionTokens: number;
47	        totalTokens: number;
48	      };
49	      finishReason: string;
50	    }
51	  | {
52	      type: "finish";
53	      finishReason: string;
54	      usage: {
55	        promptTokens: number;
56	        completionTokens: number;
57	        totalTokens: number;
58	      };
59	    }
60	  | { type: "error"; error: unknown };
61	
62	export interface VercelStreamConverterOptions {
63	  model: string;
64	}
65	
66	/**
67	 * Converts a Vercel AI SDK stream event to OpenAI ChatCompletionChunk format.
68	 * Returns null for events that don't map to OpenAI chunks (like step-start, step-finish, etc.)
69	 */
70	export function convertVercelStreamPart(
71	  part: VercelStreamPart,
72	  options: VercelStreamConverterOptions,
73	): ChatCompletionChunk | null {
74	  const { model } = options;
75	
76	  switch (part.type) {
77	    case "text-delta":
78	      return chatChunk({
79	        content: part.textDelta,
80	        model,
81	      });
82	
83	    case "reasoning":
84	      // For o1 models, reasoning is also treated as text content
85	      return chatChunk({
86	        content: part.textDelta,
87	        model,
88	      });
89	
90	    case "tool-call":
91	      return chatChunkFromDelta({
92	        delta: {
93	          tool_calls: [
94	            {
95	              index: 0,
96	              id: part.toolCallId,
97	              type: "function" as const,
98	              function: {
99	                name: part.toolName,
100	                arguments: JSON.stringify(part.args),
101	              },
102	            },
103	          ],
104	        },
105	        model,
106	      });
107	
108	    case "tool-call-delta":
109	      return chatChunkFromDelta({
110	        delta: {
111	          tool_calls: [
112	            {
113	              index: 0,
114	              function: {
115	                arguments: part.argsTextDelta,
116	              },
117	            },
118	          ],
119	        },
120	        model,
121	      });
122	
123	    case "finish":
124	      // Emit usage from finish event if available
125	      // The finish event DOES contain the final usage in most cases
126	      if (part.usage) {
127	        const promptTokens =
128	          typeof part.usage.promptTokens === "number"
129	            ? part.usage.promptTokens
130	            : 0;
131	        const completionTokens =
132	          typeof part.usage.completionTokens === "number"
133	            ? part.usage.completionTokens
134	            : 0;
135	        const totalTokens =
136	          typeof part.usage.totalTokens === "number"
137	            ? part.usage.totalTokens
138	            : promptTokens + completionTokens;
139	
140	        // Check for Anthropic-specific cache token details
141	        const promptTokensDetails =
142	          (part.usage as any).promptTokensDetails?.cachedTokens !== undefined
143	            ? {
144	                cached_tokens:
145	                  (part.usage as any).promptTokensDetails.cachedTokens ?? 0,
146	                cache_read_tokens:
147	                  (part.usage as any).promptTokensDetails.cachedTokens ?? 0,
148	                cache_write_tokens: 0,
149	              }
150	            : undefined;
151	
152	        return usageChatChunk({
153	          model,
154	          usage: {
155	            prompt_tokens: promptTokens,
156	            completion_tokens: completionTokens,
157	            total_tokens: totalTokens,
158	            ...(promptTokensDetails
159	              ? { prompt_tokens_details: promptTokensDetails as any }
160	              : {}),
161	          },
162	        });
163	      }
164	      return null;
165	
166	    case "error":
167	      // Errors should be thrown, not converted to chunks
168	      throw part.error;
169	
170	    // Events that don't map to OpenAI chunks - return null to skip
171	    case "reasoning-signature":
172	    case "redacted-reasoning":
173	    case "source":
174	    case "file":
175	    case "tool-call-streaming-start":
176	    case "tool-result":
177	    case "step-start":
178	    case "step-finish":
179	      return null;
180	
181	    default:
182	      // Exhaustiveness check
183	      const _exhaustive: never = part;
184	      return null;
185	  }
186	}
187	
188	/**
189	 * Async generator that converts Vercel AI SDK stream to OpenAI ChatCompletionChunk stream
190	 */
191	export async function* convertVercelStream(
192	  stream: AsyncIterable<VercelStreamPart>,
193	  options: VercelStreamConverterOptions,
194	): AsyncGenerator<ChatCompletionChunk, void, unknown> {
195	  for await (const part of stream) {
196	    const chunk = convertVercelStreamPart(part, options);
197	    if (chunk !== null) {
198	      yield chunk;
199	    }
200	  }
201	}
